#!/bin/sh
set -e
TARGET_USER="${USER:-$(id -un)}"

printf "Install Firefox browser? [Y/n] "
read FIREFOX_ANS
case "$FIREFOX_ANS" in n*|N*) FIREFOX_PKG="" ;; *) FIREFOX_PKG="firefox" ;; esac
printf "Install OpenCode AI CLI? [y/N] "
read OPENCODE_ANS
case "$OPENCODE_ANS" in y*|Y*) OPENCODE_WANT=1 ;; *) OPENCODE_WANT=0 ;; esac
su -c "
  sed -i 's/^#\(.*community\)/\1/' /etc/apk/repositories
  apk update
  apk add adwaita-icon-theme alpine-base alsa-ucm-conf alsa-utils bash brightnessctl busybox-mdev-openrc dbus doas dosfstools e2fsprogs elogind eudev exfatprogs ntfs-3g $FIREFOX_PKG font-awesome font-dejavu foot fuzzel gdk-pixbuf git grim grub-efi gtk+3.0 gvfs iw keyd linux-firmware linux-firmware-i915 linux-firmware-intel linux-firmware-mediatek linux-firmware-other linux-firmware-rtl_bt linux-lts linux-pam mesa-dri-gallium openssh openssl thunar pipewire pipewire-alsa pipewire-pulse polkit-elogind seatd seatd-openrc slurp sway swayidle udisks2 udisks2-openrc udev-init-scripts udev-init-scripts-openrc waybar wireless-regdb wireplumber wl-clipboard wpa_supplicant imv mpv vim engrampa 7zip zip unzip
  mkdir -p /etc/keyd
  cat << 'KEYD' > /etc/keyd/cros.conf
[ids]
k:18d1:5050
k:0000:0000
k:18d1:503c
k:18d1:5030
k:18d1:503d
k:18d1:5057
k:18d1:502b
k:18d1:504c
k:18d1:5052
k:18d1:5044
k:18d1:5061
k:18d1:505b
k:0001:0001
k:0000:0001

[main]
f1 = back
f2 = forward
f3 = refresh
f4 = f11
f5 = scale
f6 = brightnessdown
f7 = brightnessup
f8 = mute
f9 = volumedown
f10 = volumeup

back = back
forward = forward
refresh = refresh
zoom = f11
scale = scale
brightnessdown = brightnessdown
brightnessup = brightnessup
mute = mute
volumedown = volumedown
volumeup = volumeup
power = f13

f13=coffee
sleep=coffee

[meta]
f1 = f1
f2 = f2
f3 = f3
f4 = f4
f5 = f5
f6 = f6
f7 = f7
f8 = f8
f9 = f9
f10 = f10

back = f1
forward = f2
refresh = f3
zoom = f4
scale = f5
brightnessdown = f6
brightnessup = f7
mute = f8
volumedown = f9
volumeup = f10


[alt]
backspace = delete
brightnessdown = kbdillumdown
brightnessup = kbdillumup
f6 = kbdillumdown
f7 = kbdillumup

[control]
f5 = sysrq
scale = sysrq

[altgr]
backspace = delete
left = home
right = end
up = pageup
down = pagedown

[control+alt]
backspace = C-A-delete
f1 = C-A-f1
f2 = C-A-f2
f3 = C-A-f3
f4 = C-A-f4
f5 = C-A-f5
f6 = C-A-f6
f7 = C-A-f7
f8 = C-A-f8
f9 = C-A-f9
f10 = C-A-f10
back = C-A-f1
forward = C-A-f2
refresh = C-A-f3
zoom = C-A-f4
scale = C-A-f5
brightnessdown = C-A-f6
brightnessup = C-A-f7
mute = C-A-f8
volumedown = C-A-f9
volumeup = C-A-f10
KEYD
  C=/etc/wpa_supplicant/wpa_supplicant.conf
  mkdir -p /etc/wpa_supplicant
  [ -f \"\$C\" ] || touch \"\$C\"
  grep -q '^ctrl_interface=' \"\$C\" || printf 'ctrl_interface=DIR=/var/run/wpa_supplicant GROUP=wheel\n' >> \"\$C\"
  grep -q '^update_config=' \"\$C\" || printf 'update_config=1\n' >> \"\$C\"
  chmod 660 \"\$C\"
  cat << 'SA' > /usr/local/bin/supra-session-action
#!/bin/sh
# SupraOS: fixed, whitelisted root actions for the power menu (called via doas nopass).
case \"\$1\" in
  suspend) exec sh -c 'echo mem > /sys/power/state' ;;
  reboot) exec reboot ;;
  poweroff) exec poweroff ;;
  *) echo \"usage: \$0 suspend|reboot|poweroff\" >&2; exit 2 ;;
esac
SA
  chmod 755 /usr/local/bin/supra-session-action
  printf 'permit nopass %s cmd /usr/local/bin/supra-session-action\n' \"$TARGET_USER\" > /etc/doas.d/99-supra-session.conf
  printf 'auth required pam_unix.so\naccount required pam_unix.so\n' > /etc/pam.d/gtklock
  chmod 644 /etc/pam.d/gtklock
  mkdir -p /etc/polkit-1/localauthority/50-local.d
  cat << 'POLICY' > /etc/polkit-1/localauthority/50-local.d/00-supra-usb.pkla
[SupraOS USB Mount]
Identity=unix-user:erick
Action=org.freedesktop.udisks2.filesystem-mount;org.freedesktop.udisks2.filesystem-unmount;org.freedesktop.udisks2.drive-eject
ResultAny=yes
ResultInactive=yes
ResultActive=yes
POLICY
  sed -i 's/^#\?HandlePowerKey=.*/HandlePowerKey=ignore/; s/^#\?HandleLidSwitch=.*/HandleLidSwitch=ignore/; s/^#\?HandleLidSwitchExternalPower=.*/HandleLidSwitchExternalPower=ignore/' /etc/elogind/logind.conf
  mkdir -p /etc/local.d
  cat << 'BR' > /etc/local.d/brightness.start
#!/bin/sh
# SupraOS: restore last saved screen brightness (saved by the brightness keys)
b=\$(cat /home/$TARGET_USER/.cache/supra-brightness 2>/dev/null) || exit 0
max=\$(brightnessctl max) || exit 0
[ \"\$b\" -gt \"\$max\" ] && b=\$max
brightnessctl set \"\$b\" >/dev/null
BR
  chmod +x /etc/local.d/brightness.start
  rc-update add local default 2>/dev/null || true
  rc-update add devfs sysinit 2>/dev/null || true
  rc-update add dmesg sysinit 2>/dev/null || true
  rc-update add udev sysinit 2>/dev/null || true
  rc-update add udev-settle sysinit 2>/dev/null || true
  rc-update add udev-trigger sysinit 2>/dev/null || true
  rc-update add bootmisc boot 2>/dev/null || true
  rc-update add hostname boot 2>/dev/null || true
  rc-update add hwclock boot 2>/dev/null || true
  rc-update add modules boot 2>/dev/null || true
  rc-update add networking boot 2>/dev/null || true
  rc-update add seedrng boot 2>/dev/null || true
  rc-update add swap boot 2>/dev/null || true
  rc-update add sysctl boot 2>/dev/null || true
  rc-update add syslog boot 2>/dev/null || true
  rc-update add wpa_supplicant boot 2>/dev/null || true
  rc-update add cgroups default 2>/dev/null || true
  rc-update add crond default 2>/dev/null || true
  rc-update add dbus default 2>/dev/null || true
  rc-update add keyd default 2>/dev/null || true
  rc-update add ntpd default 2>/dev/null || true
  rc-update add seatd default 2>/dev/null || true
  rc-update add sshd default 2>/dev/null || true
  rc-update add udev-postmount default 2>/dev/null || true
  addgroup $TARGET_USER seat 2>/dev/null || true
  addgroup $TARGET_USER video 2>/dev/null || true
  addgroup $TARGET_USER input 2>/dev/null || true
  addgroup $TARGET_USER audio 2>/dev/null || true
  # SupraOS boot splash: copy splash image and configure GRUB for quiet boot with background
  mkdir -p /boot/grub
  cp \"$HOME/SupraOS/wallpaper/SupraOS-splash.jpg\" /boot/grub/splash.jpg 2>/dev/null || true
  if [ -f /etc/default/grub ]; then
    grep -q '^GRUB_BACKGROUND=' /etc/default/grub || echo 'GRUB_BACKGROUND=\"/boot/grub/splash.jpg\"' >> /etc/default/grub
    sed -i 's/^GRUB_BACKGROUND=.*/GRUB_BACKGROUND=\"\/boot\/grub\/splash.jpg\"/' /etc/default/grub
    sed -i 's/^GRUB_CMDLINE_LINUX_DEFAULT=\"[^\"]*\"/GRUB_CMDLINE_LINUX_DEFAULT=\"modules=sd-mod,usb-storage,ext4 quiet loglevel=0 rootfstype=ext4\"/' /etc/default/grub
    grub-mkconfig -o /boot/grub/grub.cfg 2>/dev/null || true
  fi
  # Optional toggle for boot logs (keybind-ready helper)
  cat << 'TOGGLE' > /usr/local/bin/supra-toggle-boot-logs
#!/bin/sh
# Toggle SupraOS quiet boot splash on/off
GRUB=/etc/default/grub
if grep -q 'quiet loglevel=0' \"$GRUB\"; then
  sed -i 's/quiet loglevel=0//' \"$GRUB\"
  sed -i 's/GRUB_CMDLINE_LINUX_DEFAULT=\"\(.*\)\"/GRUB_CMDLINE_LINUX_DEFAULT=\"\1 loglevel=7\"/' \"$GRUB\"
  echo 'Boot logs enabled (verbose)'
else
  sed -i 's/GRUB_CMDLINE_LINUX_DEFAULT=\"\(.*\)loglevel=[^\"]*\"/GRUB_CMDLINE_LINUX_DEFAULT=\"\1 quiet loglevel=0\"/' \"$GRUB\" || true
  sed -i 's/GRUB_CMDLINE_LINUX_DEFAULT=\"\(.*\)\"/GRUB_CMDLINE_LINUX_DEFAULT=\"\1 quiet loglevel=0\"/' \"$GRUB\"
  echo 'Boot splash enabled (quiet)'
fi
grub-mkconfig -o /boot/grub/grub.cfg 2>/dev/null || true
TOGGLE
  chmod +x /usr/local/bin/supra-toggle-boot-logs
  # Allow user to toggle via doas nopass (optional keybind)
  printf 'permit nopass %s cmd /usr/local/bin/supra-toggle-boot-logs\n' \"$TARGET_USER\" > /etc/doas.d/98-supra-toggle.conf 2>/dev/null || true
"
base64 -d << 'ARCHIVE' | tar -xzf - -C ~/ 
ARCHIVE


chmod +x ~/.local/bin/* 2>/dev/null || true
if [ "$OPENCODE_WANT" = 1 ]; then
  echo "Installing OpenCode..."
  su -c "apk add curl" || echo "warning: could not install curl"
  if curl -fsSL https://opencode.ai/install | bash; then
    if [ ! -x "$HOME/.local/bin/opencode" ] && [ -x "$HOME/.opencode/bin/opencode" ]; then
      mkdir -p "$HOME/.local/bin"
      ln -sf "$HOME/.opencode/bin/opencode" "$HOME/.local/bin/opencode"
    fi
  else
    echo "warning: opencode install failed"
  fi
fi
echo "supraOS restored! Reboot or log out and back in."
